const norm = (s: string | null | undefined) => (s || '').replace(/\s+/g, ' ').trim();

function sentenceCount(s: string): number {
  const m = s.trim().match(/[.!?](?=\s+[A-Z0-9"']|\s*$)/g);
  return m ? m.length : 0;
