import { SITE_URL, SITE_NAME, PAGES, NOT_FOUND_PAGE, getPageMeta } from '../../src/seo';

function sentenceCount(s: string): number {
  const m = s.trim().match(/[.!?](?=\s+[A-Z0-9"']|\s*$)/g);
  return m ? m.length : 0;
}

const EXPECTED_PAGES: Array<[string, string]> = [
